export function createForm(initial) {
  const values = { ...initial }, errors = {}, validators = {};
  const run = (field) => { errors[field] = validators[field] ? validators[field](values[field], values) ?? null : null; };
  return {
    values,
    errors,
    setValidator(field, validator) { validators[field] = validator; run(field); },
    set(field, value) { values[field] = value; run(field); },
    validate(field) { run(field); },
    submit(handler) {
      const failed = Object.fromEntries(Object.entries(errors).filter(([, error]) => error));
      return Object.keys(failed).length ? { ok: false, errors: failed } : { ok: true, result: handler({ ...values }) };
    },
  };
}
